import type { Issue } from "./schema"
import { RULE_PRECISION } from "./confidence-data"

export type Confidence = NonNullable<Issue["confidence"]>

/** Fewer labelled findings than this and the measured precision is noise. */
const MIN_LABELLED = 5
const HIGH = 0.85
const LOW = 0.6

/**
 * Confidence of a rule from its precision on the hand-labelled benchmark
 * (benchmark/, regenerated by `node benchmark/score.mjs --update`). A rule
 * with too few labels, or never measured, is `medium`: shown, but not vouched for.
 */
export function confidenceOf(rule: string): Confidence {
  const p = RULE_PRECISION[rule]
  if (!p || p.tp + p.fp < MIN_LABELLED) return "medium"
  const precision = p.tp / (p.tp + p.fp)
  if (precision >= HIGH) return "high"
  if (precision < LOW) return "low"
  return "medium"
}

/** Findings worth showing by default: everything but low confidence. */
export function isConfident(issue: Pick<Issue, "confidence">): boolean {
  return issue.confidence !== "low"
}
